class AsyncTicketDeskLifecycleReactiveClient(AsyncTicketDeskLifecycleClient):
    async def next_ticket_events(self, parameters: TicketEventsParams, consumer_name: str, *, batch_limit: int = 1, in_flight_limit: int = 16, lease_seconds: int = 60, maximum_wait_nanos: int = 0) -> TicketEventsBatch:
        variants = {
            "TicketCreated": TicketEventsTicketCreated,
            "TicketUpdated": TicketEventsTicketUpdated,
        }
        raw_batch = await self._transport._consume_event_batch(reactive_module_hash=TICKET_ACTIVITY_REACTIVE_MODULE_HASH, operation_name="TicketEvents", parameters=encode_reactive_record(parameters, TicketEvents_PARAMETER_SCHEMA), consumer_name=consumer_name, batch_limit=batch_limit, in_flight_limit=in_flight_limit, lease_seconds=lease_seconds, maximum_wait_nanos=maximum_wait_nanos)
        deliveries: list[TicketEventsDelivery] = []
        for item in cast(list[dict[str, Any]], raw_batch["events"]):
            raw = dict(item)
            event_type = raw.pop("type")
            if not isinstance(event_type, str): raise ValueError("invalid RiffDB event type")
            delivery_value = raw.pop("_delivery")
            if not isinstance(delivery_value, dict): raise ValueError("invalid RiffDB event delivery")
            delivery = cast(dict[str, Any], delivery_value)
            event_class = variants.get(event_type)
            if event_class is None: raise ValueError("undeclared RiffDB event")
            deliveries.append(TicketEventsDelivery(event=decode_record(event_class, raw), event_id=delivery["event_id"], attempt=delivery["attempt"], lease_token=delivery["lease_token"], expires_at=delivery["expires_at"], history_incarnation=delivery["history_incarnation"]))
        return TicketEventsBatch(events=tuple(deliveries), status=cast(dict[str, Any], raw_batch["status"]), disposition=cast(Literal["ready", "wait_timed_out", "bounded_progress"], raw_batch["disposition"]), wait_timed_out=cast(bool, raw_batch["wait_timed_out"]))

    async def ticket_events(self, parameters: TicketEventsParams, consumer_name: str) -> AsyncIterator[TicketEventsDelivery]:
        while True:
            batch = await self.next_ticket_events(parameters, consumer_name, maximum_wait_nanos=30_000_000_000)
            for delivery in batch.events:
                yield delivery

    async def ack_ticket_events(self, parameters: TicketEventsParams, consumer_name: str, delivery: TicketEventsDelivery) -> str:
        encoded = encode_reactive_record(parameters, TicketEvents_PARAMETER_SCHEMA)
        return await self._transport._acknowledge_event(reactive_module_hash=TICKET_ACTIVITY_REACTIVE_MODULE_HASH, operation_name="TicketEvents", parameters=encoded, consumer_name=consumer_name, event_id=delivery.event_id, lease_token=delivery.lease_token, history_incarnation=delivery.history_incarnation)

    async def nack_ticket_events(self, parameters: TicketEventsParams, consumer_name: str, delivery: TicketEventsDelivery, retry_delay_nanos: int = 0) -> str:
        encoded = encode_reactive_record(parameters, TicketEvents_PARAMETER_SCHEMA)
        return await self._transport._negative_acknowledge_event(reactive_module_hash=TICKET_ACTIVITY_REACTIVE_MODULE_HASH, operation_name="TicketEvents", parameters=encoded, consumer_name=consumer_name, event_id=delivery.event_id, lease_token=delivery.lease_token, history_incarnation=delivery.history_incarnation, retry_delay_nanos=retry_delay_nanos)

    async def seek_ticket_events(self, parameters: TicketEventsParams, consumer_name: str, checkpoint: str = "before-first") -> str:
        encoded = encode_reactive_record(parameters, TicketEvents_PARAMETER_SCHEMA)
        return await self._transport._seek_event_consumer(reactive_module_hash=TICKET_ACTIVITY_REACTIVE_MODULE_HASH, operation_name="TicketEvents", parameters=encoded, consumer_name=consumer_name, checkpoint=checkpoint)

    async def seek_protected_ticket_events(self, parameters: TicketEventsParams, consumer_name: str, progress_cursor: str) -> str:
        encoded = encode_reactive_record(parameters, TicketEvents_PARAMETER_SCHEMA)
        return await self._transport._seek_event_consumer(reactive_module_hash=TICKET_ACTIVITY_REACTIVE_MODULE_HASH, operation_name="TicketEvents", parameters=encoded, consumer_name=consumer_name, progress_cursor=progress_cursor)

    async def ticket_events_status(self, parameters: TicketEventsParams, consumer_name: str) -> dict[str, Any] | None:
        encoded = encode_reactive_record(parameters, TicketEvents_PARAMETER_SCHEMA)
        return await self._transport._event_consumer_status(reactive_module_hash=TICKET_ACTIVITY_REACTIVE_MODULE_HASH, operation_name="TicketEvents", parameters=encoded, consumer_name=consumer_name)

    async def watch_ticket_queue_watch(self, parameters: TicketQueueWatchParams, cursor: str | None = None) -> AsyncIterator[TicketQueueWatchUpdate]:
        outcomes = {
            "Found": TicketQueueFound,
        }
        variants = {"snapshot": TicketQueueWatchSnapshot, "patch": TicketQueueWatchPatch, "reset": TicketQueueWatchReset, "checkpoint": TicketQueueWatchCheckpoint, "terminal": TicketQueueWatchTerminal}
        encoded = encode_reactive_record(parameters, TicketQueueWatch_PARAMETER_SCHEMA)
        async for update in self._transport._watch_named_query(reactive_module_hash=TICKET_ACTIVITY_REACTIVE_MODULE_HASH, operation_name="TicketQueueWatch", parameters=encoded, cursor=cursor):
            kind = update["type"]
            update_class = variants.get(kind)
            if update_class is None: raise ValueError("undeclared RiffDB live update")
            value = decode_variant(outcomes, update["value"]) if kind in {"snapshot", "reset"} else None
            yield update_class(value=value, cursor=update.get("cursor"), metadata={key: value for key, value in update.items() if key not in {"type", "value", "cursor"}})
